-- Fas 2.5 - Luckregister och foreign keys (del 1: tabell + seed + note-kolumn)
-- Flyttar luckdefinitionerna fran data/gaps.json in i databasen. FK:erna
-- laggs i del 2 for att halla dem separata.

create table if not exists public.gaps (
  id          text primary key,
  shelf       text not null,
  cap         text,
  crop        text,
  full_img    text,
  reviewed    boolean not null default false,
  auto        text,
  note        text,
  created_at  timestamptz not null default now(),
  constraint gaps_shelf_format check (shelf ~ '^\d+:[VHSKL]\d+$')
);

alter table public.gaps enable row level security;

drop policy if exists "gaps read"   on public.gaps;
drop policy if exists "gaps insert" on public.gaps;
drop policy if exists "gaps update" on public.gaps;
drop policy if exists "gaps delete" on public.gaps;

create policy "gaps read"   on public.gaps for select to authenticated using (true);
create policy "gaps insert" on public.gaps for insert to authenticated with check (true);
create policy "gaps update" on public.gaps for update to authenticated using (true);
create policy "gaps delete" on public.gaps for delete to authenticated using (true);

comment on table public.gaps is
  'Register over kanda luckor (partier som inte gick att lasa). Fylls fran data/gaps.json i Fas 2.5 seed.';

