insert into public.gaps (id, shelf, cap, crop, full_img, reviewed, auto, note)
select
  (value->>'id')::text,
  (value->>'shelf')::text,
  (value->>'cap')::text,
  (value->>'crop')::text,
  (value->>'full_img')::text,
  coalesce((value->>'reviewed')::boolean, false),
  (value->>'auto')::text,
  (value->>'note')::text
from src
on conflict (id) do nothing;
